import{_ as t,o as a,c as o,ak as r}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"Auto-heal PRs","description":"","frontmatter":{"title":"Auto-heal PRs","lang":"en-US"},"headers":[],"relativePath":"auto-heal.md","filePath":"auto-heal.md","lastUpdated":1788684761000}'),i={name:"auto-heal.md"};function n(s,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="auto-heal-prs" tabindex="-1">Auto-heal PRs <a class="header-anchor" href="#auto-heal-prs" aria-label="Permalink to &quot;Auto-heal PRs&quot;">​</a></h1><p>When a locator breaks on your default branch and Piwi has high-confidence evidence for the replacement, it can open the fix pull request itself: a branch, a one-line locator edit per broken call site, and a body that shows the change, the score, where the replacement came from, and the command that verifies it. The CI gate runs on the PR like any other, and <a href="./ai-diagnosis.html#did-the-fix-work">fix verification</a> records the cluster as fixed once the tests pass.</p><p>It is <strong>off by default</strong>, and even once on it acts only on projects you list. Writing to your repository is the strongest thing the dashboard does, so the posture is conservative by design.</p><h2 id="what-it-does-exactly" tabindex="-1">What it does, exactly <a class="header-anchor" href="#what-it-does-exactly" aria-label="Permalink to &quot;What it does, exactly&quot;">​</a></h2><ul><li>Triggers only on a <strong>full run on the default branch</strong> — never a feature branch, and never a run reported from a heal branch (that would feed on itself).</li><li>Edits are <strong>deterministic one-line locator rewrites</strong> taken from a passing run&#39;s captured snapshot. No AI-generated code is ever in the write path.</li><li>Each edit must come from a stored snapshot (<code>prior-run</code>, <code>fingerprint</code>, or <code>cross-test</code>) and score at or above the configured minimum — or be a locator <strong>you confirmed</strong> in the picker.</li><li>Before committing, Piwi re-reads each file at the branch head and only writes lines it can still match exactly. A line that has drifted is dropped, not guessed.</li><li>One PR per run, batching every qualifying edit. A duplicate run never opens a second PR.</li></ul><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong><code>PIWI_SITE_URL</code></strong> must be set, so the links in the PR body resolve.</li><li>An <strong>SCM token with write scope</strong>, resolved the same way as <a href="./ci.html#pull-request-feedback">PR feedback</a>: a per-project token, falling back to the global one. It needs: <ul><li><strong>GitHub</strong> — <code>repo</code> (classic), or a fine-grained token with <code>contents: write</code> + <code>pull_requests: write</code>.</li><li><strong>GitLab</strong> — <code>api</code>.</li><li><strong>Bitbucket</strong> — an access token that can write to the repository. Bitbucket Cloud has no draft pull requests, so the draft setting is ignored there.</li></ul></li></ul><p>Prefer a <strong>per-project token</strong> for auto-heal: the global token grants write everywhere it reaches.</p><h2 id="enable-it" tabindex="-1">Enable it <a class="header-anchor" href="#enable-it" aria-label="Permalink to &quot;Enable it&quot;">​</a></h2><p>Settings → Auto-heal (administrator only):</p><ul><li><strong>Enabled</strong> — the master switch.</li><li><strong>Projects</strong> — the explicit allowlist. Auto-heal ignores any project not listed.</li><li><strong>Minimum score</strong> — the stability score an edit needs (default 80). A confirmed pick is always eligible.</li><li><strong>Draft</strong> — open PRs as drafts (default on; ignored on Bitbucket).</li><li><strong>Max open PRs</strong> — a per-project ceiling on simultaneously-open auto-heal PRs (default 3).</li><li><strong>Branch prefix</strong> / <strong>commit message</strong> — the branch namespace (default <code>piwi/heal/</code>) and the commit subject (default <code>test: heal broken locators</code>, a conventional-commit subject so your commit lint accepts it).</li></ul><p>You can review what Piwi has opened per project through <code>GET /api/heal-actions?projectId=&lt;id&gt;</code>.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>GitHub and GitLab and Bitbucket</strong> are supported; GitHub Enterprise is not.</li><li>The default branch is resolved per project — an explicit setting in project settings, else the repository&#39;s default branch from the SCM provider, else <code>main</code> — so the &quot;default branch only&quot; guard applies even when the reporter recorded no <code>defaultBranch</code> in its metadata.</li><li>Retries use progressive backoff and record the provider&#39;s own error on the action, so a failure is visible rather than silent.</li></ul>',14)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
